import{_ as e,o as l,c as a,a2 as n}from"./chunks/framework.DQhM5RF8.js";const x=JSON.parse('{"title":"What Enchants Go on What Gear","description":"","frontmatter":{},"headers":[],"relativePath":"enchants/gear-guide.md","filePath":"enchants/gear-guide.md"}'),s={name:"enchants/gear-guide.md"};function d(r,t,i,o,g,y){return l(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="what-enchants-go-on-what-gear" tabindex="-1">What Enchants Go on What Gear <a class="header-anchor" href="#what-enchants-go-on-what-gear" aria-label="Permalink to &quot;What Enchants Go on What Gear&quot;">​</a></h1><p>Here is the simple list showing every custom enchant in the game, where it goes, and what it does in plain English.</p><hr><h2 id="helmets" tabindex="-1">Helmets <a class="header-anchor" href="#helmets" aria-label="Permalink to &quot;Helmets&quot;">​</a></h2><p>Put these enchants on any helmet:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Enchant</th><th style="text-align:left;">Max Level</th><th style="text-align:left;">Rarity</th><th style="text-align:left;">What It Does</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Nightsight</strong></td><td style="text-align:left;">Level 1</td><td style="text-align:left;">Common</td><td style="text-align:left;">Gives you permanent Night Vision so you can see in the dark.</td></tr><tr><td style="text-align:left;"><strong>Gourmand</strong></td><td style="text-align:left;">Level 2</td><td style="text-align:left;">Common</td><td style="text-align:left;">Slowly fills your food bar so you never starve.</td></tr><tr><td style="text-align:left;"><strong>Clarity</strong></td><td style="text-align:left;">Level 2</td><td style="text-align:left;">Common</td><td style="text-align:left;">Stops you from getting blinded by squids or wardens.</td></tr><tr><td style="text-align:left;"><strong>Insight</strong></td><td style="text-align:left;">Level 3</td><td style="text-align:left;">Rare</td><td style="text-align:left;">Lets you see glowing sparkles around invisible players.</td></tr><tr><td style="text-align:left;"><strong>Protection</strong></td><td style="text-align:left;">Level 4</td><td style="text-align:left;">Vanilla</td><td style="text-align:left;">Makes you take less damage from all attacks.</td></tr><tr><td style="text-align:left;"><strong>Respiration</strong></td><td style="text-align:left;">Level 3</td><td style="text-align:left;">Vanilla</td><td style="text-align:left;">Lets you breathe underwater much longer.</td></tr><tr><td style="text-align:left;"><strong>Aqua Affinity</strong></td><td style="text-align:left;">Level 1</td><td style="text-align:left;">Vanilla</td><td style="text-align:left;">Lets you mine underwater at normal speed.</td></tr><tr><td style="text-align:left;"><strong>Unbreaking</strong></td><td style="text-align:left;">Level 3</td><td style="text-align:left;">Vanilla</td><td style="text-align:left;">Makes your helmet last way longer before breaking.</td></tr><tr><td style="text-align:left;"><strong>Mending</strong></td><td style="text-align:left;">Level 1</td><td style="text-align:left;">Vanilla</td><td style="text-align:left;">XP orbs repair your helmet automatically.</td></tr></tbody></table><hr><h2 id="chestplates" tabindex="-1">Chestplates <a class="header-anchor" href="#chestplates" aria-label="Permalink to &quot;Chestplates&quot;">​</a></h2><p>Put these enchants on any chestplate:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Enchant</th><th style="text-align:left;">Max Level</th><th style="text-align:left;">Rarity</th><th style="text-align:left;">What It Does</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Overload</strong></td><td style="text-align:left;">Level 2</td><td style="text-align:left;">Super Rare</td><td style="text-align:left;">Gives you 1 to 2 permanent extra red hearts!</td></tr><tr><td style="text-align:left;"><strong>Ironclad</strong></td><td style="text-align:left;">Level 2</td><td style="text-align:left;">Rare</td><td style="text-align:left;">Stops enemies from knocking you back when they hit you.</td></tr><tr><td style="text-align:left;"><strong>Deflection</strong></td><td style="text-align:left;">Level 3</td><td style="text-align:left;">Rare</td><td style="text-align:left;">Gives you a chance to bounce away incoming arrows with zero damage.</td></tr><tr><td style="text-align:left;"><strong>Inferno Plating</strong></td><td style="text-align:left;">Level 3</td><td style="text-align:left;">Rare</td><td style="text-align:left;">Sets attackers on fire when they hit you with a sword.</td></tr><tr><td style="text-align:left;"><strong>Purity</strong></td><td style="text-align:left;">Level 2</td><td style="text-align:left;">Common</td><td style="text-align:left;">Makes you immune to poison and wither effects.</td></tr><tr><td style="text-align:left;"><strong>Protection</strong></td><td style="text-align:left;">Level 4</td><td style="text-align:left;">Vanilla</td><td style="text-align:left;">Makes you take less damage from all hits.</td></tr><tr><td style="text-align:left;"><strong>Thorns</strong></td><td style="text-align:left;">Level 3</td><td style="text-align:left;">Vanilla</td><td style="text-align:left;">Hurts enemies back when they attack you.</td></tr><tr><td style="text-align:left;"><strong>Unbreaking</strong></td><td style="text-align:left;">Level 3</td><td style="text-align:left;">Vanilla</td><td style="text-align:left;">Makes your chestplate last way longer.</td></tr><tr><td style="text-align:left;"><strong>Mending</strong></td><td style="text-align:left;">Level 1</td><td style="text-align:left;">Vanilla</td><td style="text-align:left;">XP orbs repair your chestplate.</td></tr></tbody></table><hr><h2 id="pants-leggings" tabindex="-1">Pants (Leggings) <a class="header-anchor" href="#pants-leggings" aria-label="Permalink to &quot;Pants (Leggings)&quot;">​</a></h2><p>Put these enchants on any pair of leggings:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Enchant</th><th style="text-align:left;">Max Level</th><th style="text-align:left;">Rarity</th><th style="text-align:left;">What It Does</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Evasion</strong></td><td style="text-align:left;">Level 3</td><td style="text-align:left;">Rare</td><td style="text-align:left;">Gives you a chance to dodge sword attacks completely.</td></tr><tr><td style="text-align:left;"><strong>Adrenaline</strong></td><td style="text-align:left;">Level 3</td><td style="text-align:left;">Rare</td><td style="text-align:left;">Gives you a speed boost when someone hits you so you can escape.</td></tr><tr><td style="text-align:left;"><strong>Rejuvenation</strong></td><td style="text-align:left;">Level 2</td><td style="text-align:left;">Rare</td><td style="text-align:left;">Slowly heals your hearts after you avoid taking damage for a few seconds.</td></tr><tr><td style="text-align:left;"><strong>Protection</strong></td><td style="text-align:left;">Level 4</td><td style="text-align:left;">Vanilla</td><td style="text-align:left;">Reduces all incoming damage.</td></tr><tr><td style="text-align:left;"><strong>Swift Sneak</strong></td><td style="text-align:left;">Level 3</td><td style="text-align:left;">Vanilla</td><td style="text-align:left;">Lets you walk fast while crouching.</td></tr><tr><td style="text-align:left;"><strong>Unbreaking</strong></td><td style="text-align:left;">Level 3</td><td style="text-align:left;">Vanilla</td><td style="text-align:left;">Makes your pants last way longer.</td></tr><tr><td style="text-align:left;"><strong>Mending</strong></td><td style="text-align:left;">Level 1</td><td style="text-align:left;">Vanilla</td><td style="text-align:left;">XP orbs repair your pants.</td></tr></tbody></table><hr><h2 id="boots" tabindex="-1">Boots <a class="header-anchor" href="#boots" aria-label="Permalink to &quot;Boots&quot;">​</a></h2><p>Put these enchants on any boots:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Enchant</th><th style="text-align:left;">Max Level</th><th style="text-align:left;">Rarity</th><th style="text-align:left;">What It Does</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Swiftness</strong></td><td style="text-align:left;">Level 2</td><td style="text-align:left;">Common</td><td style="text-align:left;">Makes you run faster all the time.</td></tr><tr><td style="text-align:left;"><strong>Springs</strong></td><td style="text-align:left;">Level 2</td><td style="text-align:left;">Common</td><td style="text-align:left;">Lets you jump higher all the time.</td></tr><tr><td style="text-align:left;"><strong>Stomp</strong></td><td style="text-align:left;">Level 2</td><td style="text-align:left;">Rare</td><td style="text-align:left;">Takes less fall damage and creates a ground slam that hurts nearby mobs.</td></tr><tr><td style="text-align:left;"><strong>Feather Falling</strong></td><td style="text-align:left;">Level 4</td><td style="text-align:left;">Vanilla</td><td style="text-align:left;">Reduces fall damage so you do not die from high drops.</td></tr><tr><td style="text-align:left;"><strong>Depth Strider</strong></td><td style="text-align:left;">Level 3</td><td style="text-align:left;">Vanilla</td><td style="text-align:left;">Lets you swim and walk through water at normal walking speed.</td></tr><tr><td style="text-align:left;"><strong>Soul Speed</strong></td><td style="text-align:left;">Level 3</td><td style="text-align:left;">Vanilla</td><td style="text-align:left;">Lets you run super fast on soul sand.</td></tr><tr><td style="text-align:left;"><strong>Protection</strong></td><td style="text-align:left;">Level 4</td><td style="text-align:left;">Vanilla</td><td style="text-align:left;">Reduces all incoming damage.</td></tr><tr><td style="text-align:left;"><strong>Unbreaking</strong></td><td style="text-align:left;">Level 3</td><td style="text-align:left;">Vanilla</td><td style="text-align:left;">Makes your boots last way longer.</td></tr><tr><td style="text-align:left;"><strong>Mending</strong></td><td style="text-align:left;">Level 1</td><td style="text-align:left;">Vanilla</td><td style="text-align:left;">XP orbs repair your boots.</td></tr></tbody></table><hr><h2 id="swords" tabindex="-1">Swords <a class="header-anchor" href="#swords" aria-label="Permalink to &quot;Swords&quot;">​</a></h2><p>Put these enchants on your swords:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Enchant</th><th style="text-align:left;">Max Level</th><th style="text-align:left;">Rarity</th><th style="text-align:left;">What It Does</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Life Steal</strong></td><td style="text-align:left;">Level 3</td><td style="text-align:left;">Super Rare</td><td style="text-align:left;">Steals health from enemies and gives you extra golden hearts.</td></tr><tr><td style="text-align:left;"><strong>Bleed</strong></td><td style="text-align:left;">Level 3</td><td style="text-align:left;">Super Rare</td><td style="text-align:left;">Makes enemies bleed and take damage every second.</td></tr><tr><td style="text-align:left;"><strong>Triumph</strong></td><td style="text-align:left;">Level 3</td><td style="text-align:left;">Super Rare</td><td style="text-align:left;">Heals your hearts instantly whenever you defeat an enemy.</td></tr><tr><td style="text-align:left;"><strong>Berserker</strong></td><td style="text-align:left;">Level 1</td><td style="text-align:left;">Super Rare</td><td style="text-align:left;">Gives you super strength and speed when you are low on hearts.</td></tr><tr><td style="text-align:left;"><strong>Thunderstrike</strong></td><td style="text-align:left;">Level 3</td><td style="text-align:left;">Rare</td><td style="text-align:left;">Summons a lightning bolt from the sky to zap your target.</td></tr><tr><td style="text-align:left;"><strong>Executioner</strong></td><td style="text-align:left;">Level 3</td><td style="text-align:left;">Rare</td><td style="text-align:left;">Does massive extra damage to enemies that are low on health.</td></tr><tr><td style="text-align:left;"><strong>Backstab</strong></td><td style="text-align:left;">Level 3</td><td style="text-align:left;">Rare</td><td style="text-align:left;">Does bonus damage when you hit someone from behind.</td></tr><tr><td style="text-align:left;"><strong>Bloodlust</strong></td><td style="text-align:left;">Level 3</td><td style="text-align:left;">Rare</td><td style="text-align:left;">Hits do more damage each time you hit without missing.</td></tr><tr><td style="text-align:left;"><strong>Wither Blade</strong></td><td style="text-align:left;">Level 3</td><td style="text-align:left;">Rare</td><td style="text-align:left;">Gives enemies the black wither effect when you hit them.</td></tr><tr><td style="text-align:left;"><strong>Blinding</strong></td><td style="text-align:left;">Level 2</td><td style="text-align:left;">Rare</td><td style="text-align:left;">Blinds your target so they cannot see you for a moment.</td></tr><tr><td style="text-align:left;"><strong>Venom</strong></td><td style="text-align:left;">Level 3</td><td style="text-align:left;">Common</td><td style="text-align:left;">Poisons enemies on hit.</td></tr><tr><td style="text-align:left;"><strong>Frostbite</strong></td><td style="text-align:left;">Level 3</td><td style="text-align:left;">Common</td><td style="text-align:left;">Freezes enemies with Slowness so they cannot run away.</td></tr><tr><td style="text-align:left;"><strong>Wisdom</strong></td><td style="text-align:left;">Level 3</td><td style="text-align:left;">Common</td><td style="text-align:left;">Gives you way more XP orbs when killing mobs.</td></tr><tr><td style="text-align:left;"><strong>Feast</strong></td><td style="text-align:left;">Level 3</td><td style="text-align:left;">Common</td><td style="text-align:left;">Fills your food bar when you kill a mob.</td></tr><tr><td style="text-align:left;"><strong>Sharpness</strong></td><td style="text-align:left;">Level 5</td><td style="text-align:left;">Vanilla</td><td style="text-align:left;">Makes your sword do more damage on every hit.</td></tr><tr><td style="text-align:left;"><strong>Fire Aspect</strong></td><td style="text-align:left;">Level 2</td><td style="text-align:left;">Vanilla</td><td style="text-align:left;">Sets mobs on fire when you hit them.</td></tr><tr><td style="text-align:left;"><strong>Looting</strong></td><td style="text-align:left;">Level 3</td><td style="text-align:left;">Vanilla</td><td style="text-align:left;">Makes mobs drop way more items.</td></tr><tr><td style="text-align:left;"><strong>Unbreaking</strong></td><td style="text-align:left;">Level 3</td><td style="text-align:left;">Vanilla</td><td style="text-align:left;">Makes your sword last way longer.</td></tr><tr><td style="text-align:left;"><strong>Mending</strong></td><td style="text-align:left;">Level 1</td><td style="text-align:left;">Vanilla</td><td style="text-align:left;">XP orbs repair your sword.</td></tr></tbody></table><hr><h2 id="axes" tabindex="-1">Axes <a class="header-anchor" href="#axes" aria-label="Permalink to &quot;Axes&quot;">​</a></h2><p>Put these enchants on your battle axes:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Enchant</th><th style="text-align:left;">Max Level</th><th style="text-align:left;">Rarity</th><th style="text-align:left;">What It Does</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Cleave</strong></td><td style="text-align:left;">Level 3</td><td style="text-align:left;">Super Rare</td><td style="text-align:left;">Hits all nearby enemies in front of you in one big swing.</td></tr><tr><td style="text-align:left;"><strong>Uppercut</strong></td><td style="text-align:left;">Level 2</td><td style="text-align:left;">Rare</td><td style="text-align:left;">Launches enemies flying high up into the air.</td></tr><tr><td style="text-align:left;"><strong>Sunder</strong></td><td style="text-align:left;">Level 3</td><td style="text-align:left;">Rare</td><td style="text-align:left;">Breaks down the enemy&#39;s armor durability faster.</td></tr><tr><td style="text-align:left;"><strong>Telekinesis</strong></td><td style="text-align:left;">Level 1</td><td style="text-align:left;">Common</td><td style="text-align:left;">Cut wood goes directly into your inventory instead of falling.</td></tr><tr><td style="text-align:left;"><strong>Efficiency</strong></td><td style="text-align:left;">Level 5</td><td style="text-align:left;">Vanilla</td><td style="text-align:left;">Cuts down trees super fast.</td></tr><tr><td style="text-align:left;"><strong>Sharpness</strong></td><td style="text-align:left;">Level 5</td><td style="text-align:left;">Vanilla</td><td style="text-align:left;">Increases axe melee damage.</td></tr></tbody></table><hr><h2 id="bows-crossbows" tabindex="-1">Bows &amp; Crossbows <a class="header-anchor" href="#bows-crossbows" aria-label="Permalink to &quot;Bows &amp; Crossbows&quot;">​</a></h2><p>Put these enchants on your bows:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Enchant</th><th style="text-align:left;">Weapon</th><th style="text-align:left;">Rarity</th><th style="text-align:left;">What It Does</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Exploding Arrows</strong></td><td style="text-align:left;">Bow &amp; Crossbow</td><td style="text-align:left;">Super Rare</td><td style="text-align:left;">Arrows explode on impact like TNT.</td></tr><tr><td style="text-align:left;"><strong>Volley</strong></td><td style="text-align:left;">Bow &amp; Crossbow</td><td style="text-align:left;">Super Rare</td><td style="text-align:left;">Shoots multiple extra arrows in a spread.</td></tr><tr><td style="text-align:left;"><strong>Headshot</strong></td><td style="text-align:left;">Bow</td><td style="text-align:left;">Rare</td><td style="text-align:left;">Does huge bonus damage if you hit the enemy in the head.</td></tr><tr><td style="text-align:left;"><strong>Marksman</strong></td><td style="text-align:left;">Bow</td><td style="text-align:left;">Rare</td><td style="text-align:left;">Does more damage the farther away your target is.</td></tr><tr><td style="text-align:left;"><strong>Levitate</strong></td><td style="text-align:left;">Bow</td><td style="text-align:left;">Rare</td><td style="text-align:left;">Makes your target float up into the sky when hit.</td></tr><tr><td style="text-align:left;"><strong>Harpoon</strong></td><td style="text-align:left;">Crossbow</td><td style="text-align:left;">Rare</td><td style="text-align:left;">Pulls enemies straight toward you like a grappling hook.</td></tr><tr><td style="text-align:left;"><strong>Conservation</strong></td><td style="text-align:left;">Bow &amp; Crossbow</td><td style="text-align:left;">Common</td><td style="text-align:left;">Gives you a chance to shoot without using up your arrows.</td></tr><tr><td style="text-align:left;"><strong>Tracer</strong></td><td style="text-align:left;">Bow &amp; Crossbow</td><td style="text-align:left;">Common</td><td style="text-align:left;">Makes targets glow through walls for a few seconds.</td></tr><tr><td style="text-align:left;"><strong>Power</strong></td><td style="text-align:left;">Bow</td><td style="text-align:left;">Vanilla</td><td style="text-align:left;">Makes your arrows hit much harder.</td></tr><tr><td style="text-align:left;"><strong>Infinity</strong></td><td style="text-align:left;">Bow</td><td style="text-align:left;">Vanilla</td><td style="text-align:left;">Shoot unlimited arrows as long as you have 1 arrow.</td></tr></tbody></table><hr><h2 id="pickaxes-shovels" tabindex="-1">Pickaxes &amp; Shovels <a class="header-anchor" href="#pickaxes-shovels" aria-label="Permalink to &quot;Pickaxes &amp; Shovels&quot;">​</a></h2><p>Put these enchants on your mining tools:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Enchant</th><th style="text-align:left;">Tool</th><th style="text-align:left;">Rarity</th><th style="text-align:left;">What It Does</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Excavator</strong></td><td style="text-align:left;">Pickaxe &amp; Shovel</td><td style="text-align:left;">Super Rare</td><td style="text-align:left;">Mines out a big 3x3 square of blocks in one single swing!</td></tr><tr><td style="text-align:left;"><strong>Smelting</strong></td><td style="text-align:left;">Pickaxe</td><td style="text-align:left;">Common</td><td style="text-align:left;">Automatically turns iron and gold ore into cooked ingots.</td></tr><tr><td style="text-align:left;"><strong>Telekinesis</strong></td><td style="text-align:left;">Pickaxe &amp; Shovel</td><td style="text-align:left;">Common</td><td style="text-align:left;">Mined ores and blocks fly directly into your inventory.</td></tr><tr><td style="text-align:left;"><strong>Haste</strong></td><td style="text-align:left;">Pickaxe &amp; Shovel</td><td style="text-align:left;">Common</td><td style="text-align:left;">Gives you the Haste mining speed boost while holding it.</td></tr><tr><td style="text-align:left;"><strong>Efficiency</strong></td><td style="text-align:left;">Pickaxe &amp; Shovel</td><td style="text-align:left;">Vanilla</td><td style="text-align:left;">Mines blocks way faster.</td></tr><tr><td style="text-align:left;"><strong>Fortune</strong></td><td style="text-align:left;">Pickaxe &amp; Shovel</td><td style="text-align:left;">Vanilla</td><td style="text-align:left;">Gives you more diamonds, coal, and lapis per ore block.</td></tr><tr><td style="text-align:left;"><strong>Silk Touch</strong></td><td style="text-align:left;">Pickaxe &amp; Shovel</td><td style="text-align:left;">Vanilla</td><td style="text-align:left;">Drops the exact block (like glass, ice, or stone).</td></tr></tbody></table><hr><h2 id="maces-minecraft-1-21" tabindex="-1">Maces (Minecraft 1.21) <a class="header-anchor" href="#maces-minecraft-1-21" aria-label="Permalink to &quot;Maces (Minecraft 1.21)&quot;">​</a></h2><p>Put these enchants on the heavy mace:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Enchant</th><th style="text-align:left;">Rarity</th><th style="text-align:left;">What It Does</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Gravity Well</strong></td><td style="text-align:left;">Super Rare</td><td style="text-align:left;">Pulls all nearby players and mobs toward where you slam down.</td></tr><tr><td style="text-align:left;"><strong>Aftershock</strong></td><td style="text-align:left;">Rare</td><td style="text-align:left;">Creates a ground shockwave that slows down anyone near your hit.</td></tr><tr><td style="text-align:left;"><strong>Wind Burst</strong></td><td style="text-align:left;">Vanilla</td><td style="text-align:left;">Bounces you back up into the air when you hit someone from above.</td></tr><tr><td style="text-align:left;"><strong>Density</strong></td><td style="text-align:left;">Vanilla</td><td style="text-align:left;">Does way more damage the higher up you fall from.</td></tr><tr><td style="text-align:left;"><strong>Breach</strong></td><td style="text-align:left;">Vanilla</td><td style="text-align:left;">Ignores a chunk of the enemy&#39;s armor so your hit hurts more.</td></tr></tbody></table>',38)])])}const h=e(s,[["render",d]]);export{x as __pageData,h as default};
